import os
def write_lines(rows, path):
    d = os.path.dirname(path)
    if d:
        os.makedirs(d, exist_ok=True)
    buf = []
    for i, r in enumerate(rows):
        s = r.strip()
        if not s:
            continue
        buf.append("%d:%s\n" % (i, s))
    with open(path, "w", encoding="utf-8", newline="\n") as fh:
        fh.write("".join(buf))

